#ifndef CXGUARD_MQH
#define CXGUARD_MQH

#include "..\Interfaces\IXGuard.mqh"
#include "..\Interfaces\ICXConfig.mqh"
#include "..\Interfaces\ICXContext.mqh"
#include "..\Interfaces\CXDefine.mqh"

class CXGuard : public IXGuard {
private:
    ICXContext* m_ctx;
    string m_lastError;

    bool SetError(string msg) { m_lastError = msg; return false; }

public:
    CXGuard(ICXContext* ctx) : m_ctx(ctx) { m_lastError = ""; }
    virtual ~CXGuard() {}

    // Identification Validation
    virtual bool ValidateMagic(long magic) {
        ICXConfig* config = CX_GET_OBJ(m_ctx, "config", ICXConfig);
        if(IS_INVALID(config)) return SetError("Config not found for Magic validation");
        if(!config.IsTargetMagic(magic)) return SetError("Magic Number " + IntegerToString(magic) + " is not registered");
        return true;
    }

    virtual bool ValidateSID(string sid) {
        if(StringLen(sid) != SID_MAX_LENGTH) return SetError("Invalid SID length: " + sid);
        return true;
    }

    virtual bool ValidateGID(string gid) {
        if(StringLen(gid) != GID_MAX_LENGTH) return SetError("Invalid GID length: " + gid);
        return true;
    }

    // Trading Metric Validation
    virtual bool ValidatePrice(string symbol, double price) {
        if(price <= 0) return SetError("Price must be positive");
        double min_p = SymbolInfoDouble(symbol, SYMBOL_SESSION_PRICE_LIMIT_MIN);
        double max_p = SymbolInfoDouble(symbol, SYMBOL_SESSION_PRICE_LIMIT_MAX);
        if(min_p > 0 && price < min_p) return SetError("Price below limit: " + DoubleToString(min_p, 5));
        if(max_p > 0 && price > max_p) return SetError("Price above limit: " + DoubleToString(max_p, 5));
        return true;
    }

    virtual bool ValidateLot(string symbol, double lot) {
        double min_v = SymbolInfoDouble(symbol, SYMBOL_VOLUME_MIN);
        double max_v = SymbolInfoDouble(symbol, SYMBOL_VOLUME_MAX);
        if(lot < min_v) return SetError("Lot below minimum: " + DoubleToString(min_v, 2));
        if(lot > max_v) return SetError("Lot above maximum: " + DoubleToString(max_v, 2));
        return true;
    }

    virtual bool ValidateSlippage(int slippage) {
        if(slippage < 0 || slippage > MAX_SLIPPAGE) return SetError("Slippage out of range");
        return true;
    }

    // Price & Point Processing
    virtual double PointsToPrice(string symbol, double points) const {
        double pt = SymbolInfoDouble(symbol, SYMBOL_POINT);
        return points * pt;
    }

    virtual double NormalizePrice(string symbol, double price) const {
        int digits = (int)SymbolInfoInteger(symbol, SYMBOL_DIGITS);
        return NormalizeDouble(price, digits);
    }

    virtual bool ValidateStopLevel(string symbol, double base_price, double target_price) {
        if(target_price <= 0) return true; // Ignore if not set

        double stops_lvl = SymbolInfoInteger(symbol, SYMBOL_TRADE_STOPS_LEVEL) * SymbolInfoDouble(symbol, SYMBOL_POINT);
        double diff = MathAbs(base_price - target_price);

        if(diff < stops_lvl) {
            return SetError(StringFormat("Distance too small (StopsLevel: %.5f)", stops_lvl));
        }
        return true;
    }

    // String & Protocol Validation
    virtual bool ValidateComment(string comment) {
        if(StringLen(comment) > COMMENT_MAX_LENGTH) return SetError("Comment too long");
        return true;
    }

    virtual bool ValidateCnoBinding(int cno, long magic) {
        if((long)cno != magic) return SetError("CNO-Magic Mismatch");
        return true;
    }

    virtual string GetLastError() const { return m_lastError; }

    virtual bool Check(ICXParam* xp, ICXContext* ctx) {
        if(IS_INVALID(xp)) return true;
        ICXSignal* sig = xp.GetSignal();
        if(IS_INVALID(sig)) return true;

        if(!ValidateMagic(sig.GetMagic())) return false;
        if(!ValidateSID(sig.GetSid())) return false;

        return true;
    }
};

#endif

#ifndef CXSTEPENTRYTRAILING_MQH
#define CXSTEPENTRYTRAILING_MQH

#include "..\..\..\Interfaces\IXStep.mqh"
#include "..\..\..\Interfaces\IXPriceTracker.mqh"
#include "..\..\..\Interfaces\IXOrderManager.mqh"
#include "..\..\..\Infra\CXMessageProvider.mqh"

/**
 * @class CXStepEntryTrailing
 * @brief 지정가 주문의 실시간 가격 추적 및 수정 (Trailing Entry)
 */
class CXStepEntryTrailing : public IXStep {
public:
    virtual string Name() override { return "Step_EntryTrailing"; }

    virtual bool OnCondition(ICXParam* xp, ICXContext* ctx, int current_state) override {
        ICXSignal* sig = xp.GetSignal();
        // 주문이 배치된 상태(PENDING_PLACED)이고 트레일링 설정(te_start)이 있는 경우
        return (IS_VALID(sig) && sig.GetStatus() == XE_PENDING_PLACED && sig.GetTEStart() > 0);
    }

    virtual int OnProcess(ICXParam* xp, ICXContext* ctx) override {
        ICXSignal* sig = xp.GetSignal();
        IXOrderManager* orderMgr = CX_GET_OBJ(ctx, "order_mgr", IXOrderManager);
        IXPriceTracker* tracker = CX_GET_OBJ(ctx, "price_tracker", IXPriceTracker);

        if(IS_INVALID(sig) || IS_INVALID(orderMgr) || IS_INVALID(tracker)) return -1;

        // 1. 체결 여부 확인 (OnTradeTransaction 등에 의해 xe_status가 변경된 경우)
        if(sig.GetStatus() >= XE_EXECUTED) return SESSION_ACTIVE;

        // 2. 새로운 트레일링 가격 계산
        double point = SymbolInfoDouble(sig.GetSymbol(), SYMBOL_POINT);
        double currentPrice = SymbolInfoDouble(sig.GetSymbol(), (sig.GetDir() == CX_DIR_BUY) ? SYMBOL_BID : SYMBOL_ASK);
        tracker.Update(currentPrice);

        double dir_sign = (sig.GetDir() == CX_DIR_BUY) ? -1.0 : 1.0;
        double target = currentPrice + (sig.GetTEStart() * point * dir_sign);

        // 갱신 조건 검사 (Better Price check)
        bool is_improved = (sig.GetDir() == CX_DIR_BUY) ? (target < sig.GetPriceSignal() - sig.GetTEStep() * point) 
                                                   : (target > sig.GetPriceSignal() + sig.GetTEStep() * point);

        if(is_improved) {
            double newPrice = NormalizeDouble(target, (int)SymbolInfoInteger(sig.GetSymbol(), SYMBOL_DIGITS));

            // 3. 브로커 주문 수정 실행
            if(orderMgr.ModifyOrder((ulong)sig.GetTicket(), newPrice, sig.GetSL(), sig.GetTP())) {
                sig.SetPriceSignal(newPrice);

                CXMessageProvider::UpdateStatus(sig, sig.GetStatus(), MSG_ENTRY_TRAILING_MODIFIED);
                XP_LOG_INFO(xp, StringFormat("[TE-MODIFY] Ticket:%lld, New Price:%.5f", sig.GetTicket(), newPrice));
            }
        }

        return -1; // 상태 유지
    }

    virtual void OnEnter(ICXContext* ctx) override { XP_LOG_DEBUG(NULL, "[STEP-TE] Starting Entry Trailing Loop"); }
    virtual void OnExit(ICXContext* ctx) override { XP_LOG_DEBUG(NULL, "[STEP-TE] Exiting Entry Trailing Loop"); }
};

#endif

