                                                       : (target < sig.GetSL() - sig.GetTSStep() * point || sig.GetSL() == 0);

            if(is_improved) {
                sig.SetSL(NormalizeDouble(target, (int)SymbolInfoInteger(sig.GetSymbol(), SYMBOL_DIGITS)));
                return 1; // MODIFIED
            }
        }

        return 0; // NO_CHANGE
    }

