/**
 * @class CXAppService
 * @brief XTX 시스템의 최상위 오케스트레이터 (Root Service)
 */
class CXAppService : public ICXAppService {
private:
    ICXConfig*            m_config;
    IDatabase*            m_db;
    IRepository*          m_repo;
    ICXSignalWatcher*     m_watcher;
    ICXTradingSessionPool* m_sessionPool;
    CXReverseInjector*    m_injector;
    ICXContext*           m_globalContext;

public:
    CXAppService() : m_config(NULL), m_db(NULL), m_repo(NULL), m_watcher(NULL), m_sessionPool(NULL), m_injector(NULL), m_globalContext(NULL) {}

    virtual ~CXAppService() {
        SAFE_DELETE(m_watcher);
        SAFE_DELETE(m_injector);
        SAFE_DELETE(m_sessionPool);
        SAFE_DELETE(m_repo);
        SAFE_DELETE(m_db);
        SAFE_DELETE(m_globalContext);
    }

    /**
