private:
    void CommitCurrent() {
        if(m_tmp_from == -1 || m_tmp_step == NULL) return;
        CXStepNode* node = new CXStepNode(m_tmp_step, m_tmp_success, m_tmp_fail, m_tmp_timeout, m_tmp_retries, m_tmp_guard);
