/**
 * @class CXAppService
 * @brief XTX 시스템의 최상위 오케스트레이터 (Root Service)
 */
class CXAppService : public ICXAppService {
private:
    ICXConfig*            m_config;
    IDatabase*            m_db;
    IRepository*          m_repo;
    ICXSignalWatcher*     m_watcher;
    ICXTradingSessionPool* m_sessionPool;
    CXReverseInjector*    m_injector;
    ICXContext*           m_globalContext;

public:
    CXAppService() : m_config(NULL), m_db(NULL), m_repo(NULL), m_watcher(NULL), m_sessionPool(NULL), m_injector(NULL), m_globalContext(NULL) {}

    virtual ~CXAppService() {
        SAFE_DELETE(m_watcher);
        SAFE_DELETE(m_injector);
        SAFE_DELETE(m_sessionPool);
        SAFE_DELETE(m_repo);
        SAFE_DELETE(m_db);
        SAFE_DELETE(m_globalContext);
    }

    /**
     * @brief 전역 인프라 및 엔진 초기화
     */
    virtual bool Initialize(ICXConfig* config) override {
        m_config = config;

        m_globalContext = new CXContext();
        if(IS_INVALID(m_globalContext)) return false;
        m_globalContext.Set("config", m_config);

        m_db = new CXDatabase("XTX_Sandbox.db");
        if(IS_INVALID(m_db) || !m_db.Open()) return false;

        m_repo = new CXSignalRepository(m_db);
        m_globalContext.Set("repo", m_repo);

        IXGuard* guard = new CXGuard(config);
        m_globalContext.Set("guard", guard);

        //-- 팩토리 및 세션 풀 초기화
        CXServiceFactory* factory = new CXServiceFactory();
        m_sessionPool = new CXTradingSessionPool(10); // 최대 10개 샌드박스 병렬 실행
        m_sessionPool.Initialize(m_repo, m_globalContext, factory);
        SAFE_DELETE(factory);

        //-- 역주입 엔진 (Sync Engine) 초기화 및 초기 복구 실행
        m_injector = new CXReverseInjector(m_repo, m_sessionPool);
        if(IS_VALID(m_injector)) {
            CXParam xp;
            xp.SetContext(m_globalContext);
            m_injector.Pulse(GetPointer(xp));
        }

        //-- 감시 엔진 초기화
        m_watcher = new CXSignalWatcher(m_repo, config, m_sessionPool);

        return true;
    }

    /**
     * @brief 시스템 틱(Tick) 및 타이머 이벤트 처리
     */
    virtual void Pulse(ICXParam* xp) override {
        if(IS_INVALID(m_watcher)) return;

        m_watcher.Pulse(GetPointer(xp));

        if(IS_VALID(m_sessionPool)) m_sessionPool.Pulse(GetPointer(xp));

        // 주기적 역동기화 감시 (예: 100틱마다)
        static int tick_count = 0;
        if(++tick_count % 100 == 0 && IS_VALID(m_injector)) {
            m_injector.Pulse(GetPointer(xp));
        }
    }

