    if(IS_INVALID(activeList) || IS_INVALID(pool)) return WATCHER_DISCOVERY;

    for(int i = 0; i < activeList.Total(); i++) {
        ICXSignal* sig = CX_CAST(ICXSignal, activeList.At(i));
        if(IS_INVALID(sig)) continue;

        XP_LOG_INFO(xp, StringFormat("[BINDING] Mapping SID:%s to Sandbox Session", sig.GetSid()));

        //-- 1. 세션 풀에서 세션 대여
        ICXTradingSession* session = pool.BorrowSession();
        if(IS_VALID(session)) {
            //-- 2. 세션 기동 및 신호 주입
            CXParam sp;
            sp.SetSignal(sig);
            session.Start(GetPointer(sp));

            XP_LOG_OK(xp, StringFormat("[BINDING-SUCCESS] SID:%s mapped to active session.", sig.GetSid()));
        } else {
            XP_LOG_ERROR(xp, StringFormat("[BINDING-FAIL] No idle session available for SID:%s", sig.GetSid()));
        }
    }

    // 3. 작업 완료 후 리스트 정리 (메모리 관리: Detach 필수, Delete는 Context 소유권 정책에 따름. 여기서는 Detach 권장)
    while(activeList.Total() > 0) activeList.Detach(0); 

    return WATCHER_DISCOVERY; // 초기 상태(Discovery)로 복귀
}

