    }

    void Start(ICXParam* xp, ICXServiceFactory* factory) {
        m_isActive = true;
        InitLogger(xp.GetString(), factory);
        xp.SetEvent(EVENT_START);
        Pulse(xp);
    }

    void Start(ICXParam* xp) {
