#include <Arrays\ArrayObj.mqh>

/**
 * @class CXStepBinding
 * @brief 검증된 신호를 SessionPool에서 세션에 할당하고 기동하는 단계
 */
class CXStepBinding : public IXStep {
public:
    CXStepBinding() {}
    virtual ~CXStepBinding() {}

    virtual string Name() override { return "Step_Binding"; }

    virtual bool OnCondition(ICXParam* xp, ICXContext* ctx, int current_state) override {
        CArrayObj* activeList = (CArrayObj*)ctx.Get("active_signals");
        return (IS_VALID(activeList) && activeList.Total() > 0);
    }

    virtual int OnProcess(ICXParam* xp, ICXContext* ctx) override {
        CArrayObj* activeList = (CArrayObj*)ctx.Get("active_signals");
        ICXTradingSessionPool* pool = (ICXTradingSessionPool*)ctx.Get("session_pool");
        CXLogDispatcher* logger = (CXLogDispatcher*)ctx.Get("logger");

        if(IS_INVALID(activeList) || IS_INVALID(pool)) return 0;

        for(int i = 0; i < activeList.Total(); i++) {
            ICXSignal* sig = (ICXSignal*)activeList.At(i);
            if(IS_INVALID(sig)) continue;

            if(IS_VALID(logger)) logger.Log(LOG_LVL_INFO, StringFormat("[BINDING] Mapping SID:%s to Sandbox Session", sig.GetSid()));

            //-- 1. 세션 풀에서 세션 대여
            ICXTradingSession* session = pool.BorrowSession();
            if(IS_VALID(session)) {
                //-- 2. 세션 기동 및 신호 주입
                CXParam sp;
                sp.SetSignal(sig);
                session.Start(GetPointer(sp));

                if(IS_VALID(logger)) logger.Log(LOG_LVL_OK, StringFormat("[BINDING-SUCCESS] SID:%s mapped to active session.", sig.GetSid()));
            } else {
                if(IS_VALID(logger)) logger.Log(LOG_LVL_ERROR, StringFormat("[BINDING-FAIL] No idle session available for SID:%s", sig.GetSid()));
            }
        }

        activeList.Clear(); // 처리 완료 후 비움 (주의: CArrayObj::Clear()는 소유권이 있으면 delete함. 여기서는 포인터만 모은 것이라면 지우면 안 됨. 
                            // Discovery 단계에서 new로 생성했다면 소유권 관리가 필요. 여기서는 Detach를 권장)
        while(activeList.Total() > 0) activeList.Detach(0); 

        return 0; // 초기 상태(Discovery)로 복귀
    }

    virtual void OnEnter(ICXContext* ctx) override {}
    virtual void OnExit(ICXContext* ctx) override {}
};

#endif

