            CXParam sp;
            sp.SetSignal(sig);
            session.Start(GetPointer(sp));

            XP_LOG_OK(xp, StringFormat("[BINDING-SUCCESS] SID:%s mapped to active session.", sig.GetSid()));
        } else {
            XP_LOG_ERROR(xp, StringFormat("[BINDING-FAIL] No idle session available for SID:%s", sig.GetSid()));
        }
