virtual int OnProcess(ICXParam* xp, ICXContext* ctx) override {
    ICXSignal* sig = xp.GetSignal();
    IXPositionManager* posMgr = CX_GET_OBJ(ctx, "pos_mgr", IXPositionManager);
    IXPriceTracker* tracker = CX_GET_OBJ(ctx, "price_tracker", IXPriceTracker);

    if(IS_INVALID(sig) || IS_INVALID(posMgr) || IS_INVALID(tracker)) return STATE_UNCHANGED;

    // 1. 포지션 소멸 확인 (체결 후 사라짐 = 익절/손절/수동청산)
    if(!PositionSelectByTicket((ulong)sig.GetTicket())) {
        XP_LOG_INFO(xp, StringFormat("[TS-EXIT] Position Ticket:%lld disappeared.", sig.GetTicket()));
        return SESSION_LIQUIDATING; // 소멸 감지 시 청산 파이프라인(L1-L3)으로 진입하여 뒷정리
    }

    // 2. 트레일링 스탑 실행 (SL 업데이트)
    if(sig.GetTSStart() > 0) {
        double newSL = sig.GetSL();

        // 실제 포지션의 SL과 비교
        if(PositionSelectByTicket((ulong)sig.GetTicket())) {
            double currentSL = PositionGetDouble(POSITION_SL);
            if(MathAbs(newSL - currentSL) > 0.000001) {
                // 3. 브로커 포지션 수정 실행
                if(posMgr.ModifyPosition((ulong)sig.GetTicket(), newSL, sig.GetTP())) {
                    sig.SetSL(newSL);
                    sig.SetStatusMsg(MSG_EXIT_TS_MODIFIED);
                    XP_LOG_INFO(xp, StringFormat("[TS-MODIFY] Ticket:%lld, SL:%.5f -> %.5f\", sig.GetTicket(), sig.GetSL(), newSL));
                }
            }
        }
    }

    return STATE_UNCHANGED; // 상태 유지
}

