#ifndef CXSTEPMONITOR_MQH
#define CXSTEPMONITOR_MQH

#include "..\..\Interfaces\IXStep.mqh"
#include "..\..\Interfaces\CXDefine.mqh"
#include "..\..\Interfaces\CXMacros.mqh"
#include "..\..\Interfaces\IXPositionManager.mqh"
#include "..\..\Infra\CXMessageProvider.mqh"

/**
 * @class CXStepMonitor
 * @brief 체결된 포지션의 실시간 상태 감시 및 TP/SL 체크 (Position Monitoring)
 */
class CXStepMonitor : public IXStep {
public:
    virtual string Name() override { return "Step_Monitor"; }

    virtual bool OnCondition(ICXParam* xp, ICXContext* ctx, int current_state) override {
        ICXSignal* sig = xp.GetSignal();
        // 포지션이 살아있는 상태(EXECUTED) 확인
        return (IS_VALID(sig) && sig.GetStatus() == XE_EXECUTED);
    }

    virtual int OnProcess(ICXParam* xp, ICXContext* ctx) override {
        ICXSignal* sig = xp.GetSignal();
        if(IS_INVALID(sig)) return -1;

        // 1. 외부 청산 명령 확인 (xa_exit != XA_RAW 인 경우 즉시 청산 시퀀스 진입)
        if(sig.GetXAExit() != XA_RAW) {
            CXMessageProvider::UpdateStatus(sig, sig.GetStatus(), MSG_EXIT_REQUESTED);
            XP_LOG_INFO(xp, "[STEP-MONITOR] Exit Command Detected. Moving to LIQUIDATING.");
            return SESSION_LIQUIDATING;
        }

        // 2. 매니저를 통한 포지션 실시간 업데이트 (TP/SL 히트 여부 등)
        IXPositionManager* posMgr = CX_GET_OBJ(ctx, "pos_mgr", IXPositionManager);
        if(IS_VALID(posMgr)) {
            posMgr.Pulse(xp);
        }

        // 3. 트레일링 설정이 있는 경우 트레일링 단계로 전이
        if(sig.GetTSStart() > 0) {
            return STATE_EXIT_TRAILING;
        }

        return -1; // 상태 유지
    }

    virtual void OnEnter(ICXContext* ctx) override { XP_LOG_DEBUG(NULL, "[STEP-MONITOR] Starting Position Monitoring"); }
    virtual void OnExit(ICXContext* ctx) override { XP_LOG_DEBUG(NULL, "[STEP-MONITOR] Stopping Position Monitoring"); }
};

#endif

#ifndef CXSTEPENTRYTRAILING_MQH
#define CXSTEPENTRYTRAILING_MQH

#include "..\..\..\Interfaces\IXStep.mqh"
#include "..\..\..\Interfaces\IXPriceTracker.mqh"
#include "..\..\..\Interfaces\IXOrderManager.mqh"
#include "..\..\..\Infra\CXMessageProvider.mqh"

/**
 * @class CXStepEntryTrailing
 * @brief 지정가 주문의 실시간 가격 추적 및 수정 (Trailing Entry)
 */
class CXStepEntryTrailing : public IXStep {
public:
    virtual string Name() override { return "Step_EntryTrailing"; }

    virtual bool OnCondition(ICXParam* xp, ICXContext* ctx, int current_state) override {
        ICXSignal* sig = xp.GetSignal();
        // 주문이 배치된 상태(PENDING_PLACED)이고 트레일링 설정(te_start)이 있는 경우
        return (IS_VALID(sig) && sig.GetStatus() == XE_PENDING_PLACED && sig.GetTEStart() > 0);
    }

    virtual int OnProcess(ICXParam* xp, ICXContext* ctx) override {
        ICXSignal* sig = xp.GetSignal();
        IXOrderManager* orderMgr = CX_GET_OBJ(ctx, "order_mgr", IXOrderManager);
        IXPriceTracker* tracker = CX_GET_OBJ(ctx, "price_tracker", IXPriceTracker);

        if(IS_INVALID(sig) || IS_INVALID(orderMgr) || IS_INVALID(tracker)) return -1;

        // 1. 체결 여부 확인 (OnTradeTransaction 등에 의해 xe_status가 변경된 경우)
        if(sig.GetStatus() >= XE_EXECUTED) return SESSION_ACTIVE;

        // 2. 새로운 트레일링 가격 계산
        double point = SymbolInfoDouble(sig.GetSymbol(), SYMBOL_POINT);
        double currentPrice = SymbolInfoDouble(sig.GetSymbol(), (sig.GetDir() == CX_DIR_BUY) ? SYMBOL_BID : SYMBOL_ASK);
        tracker.Update(currentPrice);

        double dir_sign = (sig.GetDir() == CX_DIR_BUY) ? -1.0 : 1.0;
        double target = currentPrice + (sig.GetTEStart() * point * dir_sign);

        // 갱신 조건 검사 (Better Price check)
        bool is_improved = (sig.GetDir() == CX_DIR_BUY) ? (target < sig.GetPriceSignal() - sig.GetTEStep() * point) 
                                                   : (target > sig.GetPriceSignal() + sig.GetTEStep() * point);

        if(is_improved) {
            double newPrice = NormalizeDouble(target, (int)SymbolInfoInteger(sig.GetSymbol(), SYMBOL_DIGITS));

            // 3. 브로커 주문 수정 실행
            if(orderMgr.ModifyOrder((ulong)sig.GetTicket(), newPrice, sig.GetSL(), sig.GetTP())) {
                sig.SetPriceSignal(newPrice);

                CXMessageProvider::UpdateStatus(sig, sig.GetStatus(), MSG_ENTRY_TRAILING_MODIFIED);
                XP_LOG_INFO(xp, StringFormat("[TE-MODIFY] Ticket:%lld, New Price:%.5f", sig.GetTicket(), newPrice));
            }
        }

        return -1; // 상태 유지
    }

    virtual void OnEnter(ICXContext* ctx) override { XP_LOG_DEBUG(NULL, "[STEP-TE] Starting Entry Trailing Loop"); }
    virtual void OnExit(ICXContext* ctx) override { XP_LOG_DEBUG(NULL, "[STEP-TE] Exiting Entry Trailing Loop"); }
};

#endif

#ifndef CXSTEPEXITTRAILING_MQH
#define CXSTEPEXITTRAILING_MQH

#include "..\..\..\Interfaces\IXStep.mqh"
#include "..\..\..\Interfaces\IXPriceTracker.mqh"
#include "..\..\..\Interfaces\IXPositionManager.mqh"
#include "..\..\..\Models\CXSignal.mqh"

/**
 * @class CXStepExitTrailing
 * @brief 체결된 포지션의 수익 보존을 위한 익절 트레일링(Ik-Te/TS)
 */
class CXStepExitTrailing : public IXStep {
public:
    virtual string Name() override { return "Step_ExitTrailing"; }

    virtual bool OnCondition(ICXParam* xp, ICXContext* ctx, int current_state) override {
        ICXSignal* sig = xp.GetSignal();
        // 체결된 상태(EXECUTED)이고 트레일링 설정(ts_start)이 있는 경우
        return (IS_VALID(sig) && sig.GetStatus() == XE_EXECUTED && sig.GetTSStart() > 0);
    }

    virtual int OnProcess(ICXParam* xp, ICXContext* ctx) override {
        ICXSignal* sig = xp.GetSignal();
        IXPositionManager* posMgr = CX_GET_OBJ(ctx, "pos_mgr", IXPositionManager);
        IXPriceTracker* tracker = CX_GET_OBJ(ctx, "price_tracker", IXPriceTracker);

        if(IS_INVALID(sig) || IS_INVALID(posMgr) || IS_INVALID(tracker)) return -1;

        // 1. 외부 청산 신호 확인
        if(sig.GetXAExit() != XA_RAW) return SESSION_LIQUIDATING;

        // 2. 새로운 트레일링 SL 가격 계산
        double point = SymbolInfoDouble(sig.GetSymbol(), SYMBOL_POINT);
        double currentPrice = SymbolInfoDouble(sig.GetSymbol(), (sig.GetDir() == CX_DIR_BUY) ? SYMBOL_BID : SYMBOL_ASK);
        tracker.Update(currentPrice);

        double dir_sign = (sig.GetDir() == CX_DIR_BUY) ? 1.0 : -1.0;
        double profit = (currentPrice - sig.GetPriceOpen()) * dir_sign;

        if(profit >= sig.GetTSStart() * point) {
            double peak = (sig.GetDir() == CX_DIR_BUY) ? tracker.GetHighest() : tracker.GetLowest();
            double target = peak - (sig.GetTSStart() * point * dir_sign);

            // 갱신 조건 검사 (Better SL check)
            bool is_improved = (sig.GetDir() == CX_DIR_BUY) ? (target > sig.GetSL() + sig.GetTSStep() * point)
                                                       : (target < sig.GetSL() - sig.GetTSStep() * point || sig.GetSL() == 0);

            if(is_improved) {
                double newSL = NormalizeDouble(target, (int)SymbolInfoInteger(sig.GetSymbol(), SYMBOL_DIGITS));

                // 3. 브로커 포지션 수정 실행
                if(posMgr.ModifyPosition((ulong)sig.GetTicket(), newSL, sig.GetTP())) {
                    sig.SetSL(newSL);
                    sig.SetStatusMsg(MSG_EXIT_TS_MODIFIED);
                    XP_LOG_INFO(xp, StringFormat("[TS-MODIFY] Ticket:%lld, SL:%.5f -> %.5f", sig.GetTicket(), sig.GetSL(), newSL));
                }
            }
        }

        return -1; // 상태 유지
    }

    virtual void OnEnter(ICXContext* ctx) override { XP_LOG_DEBUG(NULL, "[STEP-TS] Starting Exit Trailing Loop"); }
    virtual void OnExit(ICXContext* ctx) override { XP_LOG_DEBUG(NULL, "[STEP-TS] Exiting Exit Trailing Loop"); }
};

#endif

