    /**
     * @brief Layer 1: 티켓 기반 정밀 청산
     */
    virtual bool CloseByTicket(ICXSignal* sig) override {
        if(sig.GetTicket() <= 0) return true; // 이미 티켓이 없는 경우 성공으로 간주

        bool res = false;
        if(PositionSelectByTicket((ulong)sig.GetTicket())) {
            res = m_trade.PositionClose((ulong)sig.GetTicket());
        }
        else if(OrderSelect((ulong)sig.GetTicket())) {
            res = m_trade.OrderDelete((ulong)sig.GetTicket());
        }
        else {
            return true; // 티켓을 찾을 수 없는 경우(이미 소멸) 성공
        }
        return res;
    }

